create table if not exists public.curated_operation_owners (id bigint generated by default as identity primary key, network_key text not null, calendar_type text not null, effective_from date not null, operation_code text not null, owner_operator text not null, vehicle_type text, source_url text not null, evidence_grade text not null default 'C', source_path text not null, created_at timestamptz not null default now(), constraint curated_operation_owners_unique unique (network_key,calendar_type,effective_from,operation_code)); alter table public.curated_operation_owners enable row level security; create index if not exists curated_operation_owners_lookup on public.curated_operation_owners(network_key,calendar_type,effective_from,operation_code); comment on table public.curated_operation_owners is 'Verified static timetable operation ownership evidence; not ODPT live or API timetable cache.';
